examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4)) {
    LazyColumn(modifier = Modifier.height(MonarchTheme.spacing.space24 * 3), state = state) {
        articleSections.forEach { (meta, paragraphs) ->
            item(key = meta.first) {
                MonarchText(
                    text = meta.second,
                    style = if (meta.third == 2) MonarchTextStyle.Heading else MonarchTextStyle.Subheading,
                )
            }
            items(paragraphs) { paragraph -> MonarchText(text = paragraph) }
        }
    }
    MonarchTableOfContents(
        items = articleSections.map { (meta, _) ->
            MonarchTableOfContentsItem(title = meta.second, id = meta.first, level = meta.third)
        },
        selectedId = current,
        onSelect = { id -> scope.launch { state.animateScrollToItem(sections.getValue(id)) } },
        title = {{title}},
    )
}

